#include <string>
#include <string_view>
#include <stdio.h>
#include <windows.h>

#include "globals.h"

// Mostly generated by Copilot

// Helper function to create a test file
void CreateTestFile(const std::wstring& filename, size_t size) {
    HANDLE hFile = CreateFile(
        filename.c_str(),
        GENERIC_WRITE,
        0,
        NULL,
        CREATE_NEW,
        FILE_ATTRIBUTE_NORMAL,
        NULL
    );
    if (hFile != INVALID_HANDLE_VALUE)
    {
    	char buffer[size]; // uninitialized on purpose
		WriteFile(hFile, buffer, size, nullptr, nullptr);
        CloseHandle(hFile);
    }
}

// Helper function to delete a test file
void DeleteTestFile(const std::wstring& filename) {
    DeleteFile(filename.c_str());
}

// Test suite for FindFirstFile
void SetUp()
{
	// Create test files
	CreateTestFile(L"testfile1.txt", 1);
	CreateTestFile(L"testfile2.txt", 2);
	CreateTestFile(L"testfile3.log", 3);
	CreateDirectory(L"existentpath", nullptr);
	CreateTestFile(L"existentpath/testfile1.txt", 1);
}

void TearDown()
{
	// Delete test files
	DeleteTestFile(L"testfile1.txt");
	DeleteTestFile(L"testfile2.txt");
	DeleteTestFile(L"testfile3.log");
	DeleteTestFile(L"existentpath/testfile1.txt");
	RemoveDirectory(L"existentpath");
}

void FindExistingFiles()
{
    WIN32_FIND_DATA findFileData;
    HANDLE hFind = FindFirstFile(L"testfile*.txt", &findFileData);

    if (hFind == INVALID_HANDLE_VALUE)
	{
		failure("FindExistingFiles expected to find files but got INVALID_HANDLE_VALUE\n");
		return;
	}

    // Check first file found
    std::wstring firstFile = findFileData.cFileName;
    if (!(firstFile == L"testfile1.txt" || firstFile == L"testfile2.txt"))
	{
		failure("FindExistingFiles found wrong file %S\n", firstFile.c_str());
	}

	if ((firstFile == L"testfile1.txt" && findFileData.nFileSizeLow != 1) ||
		(firstFile == L"testfile2.txt" && findFileData.nFileSizeLow != 2))
	{
		failure("FindFirstFile found file %S with wrong size %u\n", firstFile.c_str(), (unsigned)findFileData.nFileSizeLow);
	}

	if (findFileData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)
	{
		failure("FindFirstFile returned directory attribute for file %S\n", firstFile.c_str());
	}

    // Find next file
    while (FindNextFile(hFind, &findFileData)) {
        std::wstring nextFile = findFileData.cFileName;
        if (!(nextFile == L"testfile1.txt" || nextFile == L"testfile2.txt"))
		{
			failure("FindNexFile found wrong file %S\n", nextFile.c_str());
		}

		if ((nextFile == L"testfile1.txt" && findFileData.nFileSizeLow != 1) ||
			(nextFile == L"testfile2.txt" && findFileData.nFileSizeLow != 2))
		{
			failure("FindNextFile found file %S with wrong size %u\n", nextFile.c_str(), (unsigned)findFileData.nFileSizeLow);
		}

    }

    FindClose(hFind);
}

void NoMatchingFiles()
{
    WIN32_FIND_DATA findFileData;
    HANDLE hFind = FindFirstFile(L"nonexistentfile*.txt", &findFileData);

    if (hFind != INVALID_HANDLE_VALUE)
	{
		FindClose(hFind);
		failure("Expected INVALID_HANDLE_VALUE for no matching files\n");
	}
	else
	{
		DWORD err = GetLastError();
		if (err != ERROR_FILE_NOT_FOUND)
		{
			failure("FindFirstFile returned %lu instead of ERROR_FILE_NOT_FOUND\n", err);
		}
	}
}

void FindDifferentPattern()
{
    WIN32_FIND_DATA findFileData;
    HANDLE hFind = FindFirstFile(L"testfile*.log", &findFileData);

    if (hFind == INVALID_HANDLE_VALUE)
	{
		failure("FindFirstFile expected to find other files but got INVALID_HANDLE_VALUE\n");
		return;
	}

    std::wstring firstFile = findFileData.cFileName;
    if (firstFile != L"testfile3.log")
	{
		failure("FindFirstFile found %S instead of testfile.log\n", firstFile.c_str());
	}

    FindClose(hFind);
}

using namespace std::literals::string_view_literals;

constexpr const WCHAR* const expectedNames[] =
{
	L"testfile1.txt",
	L"testfile2.txt",
	L"testfile3.log",
	L".",
	L"..",
	L"tests.exe",
	L"tests",
	L"testdll.so",
	L"testdll.dll",
	L"libpathcch.a",
	L"obj",
	L"existentpath"
};

void MatchAllFiles(const wchar_t* pattern)
{
    WIN32_FIND_DATA findFileData;
    HANDLE hFind = FindFirstFile(pattern, &findFileData);

    if (hFind == INVALID_HANDLE_VALUE)
	{
		failure("FindFirstFile expected to match all files but got INVALID_HANDLE_VALUE\n");
		return;
	}

    // List all files
    do
    {
		bool found = false;
		for (const WCHAR* itr : expectedNames)
		{
			if (std::wstring_view(findFileData.cFileName) == std::wstring_view(itr))
			{
				found = true;
				break;
			}
		}
		if (!found)
		{
			failure("FindFirstFile found unexpected file: %S\n", findFileData.cFileName);
		}

		if (std::wstring_view(findFileData.cFileName) == L".."sv && (findFileData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) == 0)
		{
			failure("FindFirstFile didn't return directory attribute for file %S\n", findFileData.cFileName);
		}
    } while (FindNextFile(hFind, &findFileData));

    DWORD err = GetLastError();
    if (err != ERROR_NO_MORE_FILES)
	{
		failure("FindNextFile returned %lu instead of ERROR_NO_MORE_FILES\n", err);
	}

    FindClose(hFind);
}

void InvalidPath()
{
    WIN32_FIND_DATA findFileData;
    HANDLE hFind = FindFirstFile(L"nonexistentpath\\*.*", &findFileData);

    if (hFind != INVALID_HANDLE_VALUE)
	{
		failure("Expected INVALID_HANDLE_VALUE for invalid path\n");
		FindClose(hFind);
		return;
	}
	DWORD err = GetLastError();
    if (err != ERROR_PATH_NOT_FOUND)
	{
		failure("FindFirstFile expected ERROR_PATH_NOT_FOUND for invalid path but returned %lu\n", err);
	}
}

