void RunFindTests()
{
	SetUp();

	FindExistingFiles();
	NoMatchingFiles();
	FindDifferentPattern();
	MatchAllFiles(L"*");
	MatchAllFiles(L"existentpath/*");
	InvalidPath();

	TearDown();
}
